using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(UriTemplate = "config://app/settings",
    Name = "AppSettings",
    Description = "Returns the current application configuration data",
    MimeType = "application/json")]
public class ConfigResource
{
    private static readonly Dictionary<string, object> Settings = new()
    {
        ["environment"] = "production",
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        }
    };

    public static string GetConfigJson() =>
        JsonSerializer.Serialize(Settings, new JsonSerializerOptions { WriteIndented = true });
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Gets the current server status and uptime")]
    public static string GetStatus()
    {
        return $"Server is running. Uptime: {Environment.TickCount64 / 1000}s";
    }

    [McpServerTool, Description("Echoes back the provided message")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

