namespace McpHttpServer;

[McpServerResourceType]
public static class ConfigResource
{
    private static readonly Dictionary<string, object> Settings = new()
    {
        ["environment"] = "production",
        ["maxRetries"] = 3,
        ["timeoutSeconds"] = 30,
        ["features"] = new Dictionary<string, bool>
        {
            ["darkMode"] = true,
            ["notifications"] = true,
            ["betaFeatures"] = false
        }
    };

    [McpServerResource(UriTemplate = "config://app/settings",
        Name = "AppSettings",
        MimeType = "application/json")]
    public static string GetSettings()
    {
        return JsonSerializer.Serialize(Settings, new JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(UriTemplate = "config://app/features/{featureName}",
        Name = "FeatureFlag",
        MimeType = "application/json")]
    public static string GetFeatureFlag(string featureName)
    {
        var features = (Dictionary<string, bool>)Settings["features"];
        if (features.TryGetValue(featureName, out var enabled))
            return JsonSerializer.Serialize(new { feature = featureName, enabled });

        return JsonSerializer.Serialize(new { feature = featureName, error = "not found" });
    }
}

